import React, { useEffect, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { motion } from 'motion/react';
import {
  AlertCircle,
  ArrowRight,
  Building2,
  CheckCircle2,
  Loader2,
  ShieldCheck,
} from 'lucide-react';
import { SEO } from '../components/SEO';
import { useAuth } from '../context/AuthContext';
import { supabase } from '../lib/supabase';

type InviteDetails = {
  valid?: boolean;
  error?: string;
  name?: string;
  description?: string;
  role?: 'admin' | 'member';
  expires_at?: string;
};

export const BusinessChatInvitePage = () => {
  const { token } = useParams<{ token: string }>();
  const { user } = useAuth();
  const navigate = useNavigate();
  const [details, setDetails] = useState<InviteDetails | null>(null);
  const [loading, setLoading] = useState(true);
  const [joining, setJoining] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    let active = true;
    const loadInvite = async () => {
      if (!token) {
        setError('This business chat invite is missing its token.');
        setLoading(false);
        return;
      }
      try {
        const { data, error: rpcError } = await supabase.rpc('get_business_chat_invite_details', {
          p_token: token,
        });
        if (rpcError) throw rpcError;
        const nextDetails = data as InviteDetails | null;
        if (!nextDetails?.valid) throw new Error(nextDetails?.error || 'This invitation is invalid.');
        if (active) setDetails(nextDetails);
      } catch (reason) {
        if (active) {
          setError(reason instanceof Error ? reason.message : 'This invitation is invalid.');
        }
      } finally {
        if (active) setLoading(false);
      }
    };
    void loadInvite();
    return () => {
      active = false;
    };
  }, [token]);

  const joinBusinessChat = async () => {
    if (!token) return;
    if (!user) {
      navigate(`/auth?redirect=${encodeURIComponent(window.location.pathname)}`);
      return;
    }
    setJoining(true);
    setError('');
    try {
      const { data, error: rpcError } = await supabase.rpc('accept_business_chat_invite', {
        p_token: token,
      });
      if (rpcError) throw rpcError;
      const result = data as { success?: boolean; business_chat_id?: string; chat_id?: string } | null;
      if (!result?.success || !result.business_chat_id) throw new Error('Wersee could not join this business chat.');
      const query = new URLSearchParams({
        business: result.business_chat_id,
        ...(result.chat_id ? { chat: result.chat_id } : {}),
      });
      navigate(`/workspace/chats?${query.toString()}`, { replace: true });
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : 'Wersee could not join this business chat.');
      setJoining(false);
    }
  };

  const pageTitle = details?.name ? `Join ${details.name}` : 'Business chat invitation';

  return (
    <main className="flex min-h-screen items-center justify-center bg-[#09090b] p-4 text-white">
      <SEO
        title={pageTitle}
        description="Join a private Wersee business chat."
        url={token ? `/business-chat/invite/${token}` : '/business-chat/invite'}
        noIndex
      />
      <motion.section
        initial={{ opacity: 0, y: 18, scale: 0.98 }}
        animate={{ opacity: 1, y: 0, scale: 1 }}
        className="w-full max-w-md rounded-[32px] border border-white/10 bg-[#151518] p-7 text-center shadow-2xl md:p-9"
      >
        {loading ? (
          <div className="grid min-h-56 place-items-center">
            <span>
              <Loader2 className="mx-auto h-7 w-7 animate-spin text-violet-300" />
              <span className="mt-4 block text-sm text-white/45">Checking your invitation…</span>
            </span>
          </div>
        ) : error ? (
          <>
            <span className="mx-auto grid h-16 w-16 place-items-center rounded-3xl border border-red-400/20 bg-red-400/10 text-red-300">
              <AlertCircle className="h-7 w-7" />
            </span>
            <h1 className="mt-6 text-2xl font-bold">Invitation unavailable</h1>
            <p className="mt-3 text-sm leading-6 text-white/50">{error}</p>
            <button
              type="button"
              onClick={() => navigate('/workspace/chats')}
              className="mt-7 min-h-12 w-full rounded-2xl bg-white px-5 text-sm font-bold text-black"
            >
              Open Wersee Chat
            </button>
          </>
        ) : (
          <>
            <span className="mx-auto grid h-20 w-20 place-items-center rounded-[26px] border border-violet-400/20 bg-violet-400/10 text-violet-200">
              <Building2 className="h-9 w-9" />
            </span>
            <p className="mt-6 text-xs font-bold uppercase tracking-[0.16em] text-violet-300/70">Wersee business chat</p>
            <h1 className="mt-2 text-3xl font-bold tracking-tight">{details?.name}</h1>
            {details?.description && (
              <p className="mt-3 text-sm leading-6 text-white/50">{details.description}</p>
            )}
            <span className="mx-auto mt-5 inline-flex items-center gap-1.5 rounded-full bg-white/[0.06] px-3 py-1.5 text-xs font-semibold capitalize text-white/60">
              {details?.role === 'admin' ? <ShieldCheck className="h-3.5 w-3.5" /> : <CheckCircle2 className="h-3.5 w-3.5" />}
              Join as {details?.role || 'member'}
            </span>
            <button
              type="button"
              onClick={() => void joinBusinessChat()}
              disabled={joining}
              className="mt-7 flex min-h-14 w-full items-center justify-center gap-2 rounded-2xl bg-white px-5 text-base font-bold text-black transition active:scale-[0.99] disabled:opacity-50"
            >
              {joining
                ? <Loader2 className="h-5 w-5 animate-spin" />
                : user
                  ? 'Join business chat'
                  : 'Sign in and join'}
              {!joining && <ArrowRight className="h-5 w-5" />}
            </button>
            <p className="mt-4 text-[11px] leading-5 text-white/30">
              This personal invitation only works with the email address that received it.
            </p>
          </>
        )}
      </motion.section>
    </main>
  );
};

